-- Reverse the Words (Easy)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$reverse-words$q$, $q$Reverse the Words$q$, $q$Words are runs of letters and digits separated by one or more spaces. The line may have spaces at the start and the end.

Print the words in reverse order, separated by exactly one space, with no leading or trailing spaces. The letters inside each word keep their order. If the line contains no words, print an empty line.$q$, $q$Easy$q$, $q$Strings$q$, 'code', ARRAY[$q$string$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # One line of text.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// One line of text.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // One line of text.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // One line of text.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // One line of text.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "  the sky   is blue ", "output": "blue is sky the", "explanation": "Extra spaces disappear."}, {"input": "solo", "output": "solo", "explanation": "One word stays as it is."}]$q$::jsonb, ARRAY[$q$0 ≤ length of the line ≤ 30 000$q$, $q$Characters are letters, digits and spaces$q$]::text[], 10, 1003, 2000, 262144, $q$One line of text.$q$, $q$The words in reverse order, single-space separated.$q$, $q$Split on runs of whitespace, reverse the list, join with a single space. Splitting by a single space instead leaves empty strings in the list, which is the usual bug. O(n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

